struct NumMatrix{p:Vec<Vec<i32>>}impl NumMatrix{fn new(a:Vec<Vec<i32>>)->Self{let m=a.len();let n=if m>0{a[0].len()}else{0};let mut p=vec![vec![0;n+1];m+1];for i in 0..m{for j in 0..n{p[i+1][j+1]=a[i][j]+p[i][j+1]+p[i+1][j]-p[i][j];}}Self{p}}fn sum_region(&self,r1:i32,c1:i32,r2:i32,c2:i32)->i32{self.p[r2 as usize+1][c2 as usize+1]-self.p[r1 as usize][c2 as usize+1]-self.p[r2 as usize+1][c1 as usize]+self.p[r1 as usize][c1 as usize]}}
